package com.hibernate.ecommerce.model;import jakarta.persistence.Entity;import jakarta.persistence.GeneratedValue;import jakarta.persistence.GenerationType;import jakarta.persistence.Id;import jakarta.validation.constraints.Email;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.NotNull;import lombok.*;import org.hibernate.annotations.CreationTimestamp;import java.time.LocalDateTime;@Entity@Getter @Setter@AllArgsConstructor@NoArgsConstructor@Builderpublic class Client {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @NotNull    @NotBlank    private String name;    @NotNull    @NotBlank    private String phone;    @Email    @NotNull    @NotBlank    private String email;    @CreationTimestamp    private LocalDateTime registerDate;}